INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q570204', 'Battle of the Kalka River', 'The Battle of the Kalka River was fought between the Mongol Empire, whose armies were led by Jebe and Subutai, and a coalition of several Rus'' principalities, including Kiev and Galicia-Volhynia, and the Cumans under Köten. They were under the joint command of Mstislav the Bold and Mstislav III of Kiev.', 1223, 5, 31, NULL, NULL, NULL, 'day', '31 May 1223', 74, 'https://en.wikipedia.org/wiki/Battle_of_the_Kalka_River'),
  ('Q521799', 'Battle of the Neva', 'The Battle of the Neva (Russian: Невская битва, romanized: Nevskaya bitva; Swedish: slaget vid Neva; Finnish: Nevan taistelu) was fought between the Novgorod Republic, along with Karelians, and the Kingdom of Sweden, including Norwegian, Finnish and Tavastian forces, on the Neva River, near the settlement of Ust-Izhora, on 15 July 1240. The battle is mentioned only in Russian sources, and it remains unclear whether it was a major invasion or a small-scale raid.', 1240, 7, 15, NULL, NULL, NULL, 'day', '15 July 1240', 71, 'https://en.wikipedia.org/wiki/Battle_of_the_Neva'),
  ('Q210354', 'Battle of Kulikovo', 'The Battle of Kulikovo (Russian: Куликовская битва, romanized: Kulikovskaya bitva) was fought between the forces of Mamai, a powerful Mongol military commander of the Golden Horde, and Russian forces led by Grand Prince Dmitry of Moscow. The battle took place on 8 September 1380, at Kulikovo Field near the Don River (now Tula Oblast, Russia) and was won by Dmitry, who became known as Donskoy ("of the Don") after the battle.', 1380, 9, 8, NULL, NULL, NULL, 'day', '8 September 1380', 75, 'https://en.wikipedia.org/wiki/Battle_of_Kulikovo'),
  ('Q25628', 'Great stand on the Ugra river', 'The Great Stand on the Ugra River (Russian: Великое стояние на Угре) or the Standing on the Ugra River, also known as the Battle of the Ugra, was a standoff in 1480 on the banks of the Ugra River between the forces of Akhmat Khan of the Great Horde, and Grand Prince Ivan III of the Grand Duchy of Moscow. After Ivan III stopped paying tribute to the Horde, Akhmat Khan led an army towards Moscow, leading to a standoff between the two armies on the banks of the river.', 1480, NULL, NULL, NULL, NULL, NULL, 'year', '1480', 64, 'https://en.wikipedia.org/wiki/Great_Stand_on_the_Ugra_River'),
  ('Q631799', 'First Russo-Turkish War', 'The Russo-Turkish War (1568–1570) or Don-Volga-Astrakhan campaign of 1569 (referred to in Ottoman sources as the Astrakhan Expedition) was a war between the Tsardom of Russia and the Ottoman Empire over the Astrakhan Khanate. It was the first of twelve Russo-Turkish wars ending with World War I in 1914–18.', 1568, NULL, NULL, 1570, NULL, NULL, 'year', '1568–1570', 71, 'https://en.wikipedia.org/wiki/Russo-Turkish_War_(1568%E2%80%931570)'),
  ('Q37853', 'Baroque', 'The Baroque (UK: bə-ROK, US: bə-ROHK, French: [baʁɔk]) is a Western style of architecture, music, dance, painting, sculpture, poetry, and other arts that flourished from the early 1600s until the 1750s. It followed Renaissance art and Mannerism and preceded the Rococo (in the past often referred to as "late Baroque") and Neoclassical styles.', 1590, NULL, NULL, 1750, NULL, NULL, 'century', '16th century – 1750s', 92, 'https://en.wikipedia.org/wiki/Baroque'),
  ('Q1962709', 'Ingrian War', 'The Ingrian War (Swedish: Ingermanländska kriget) was a conflict fought between the Swedish Empire and the Tsardom of Russia which lasted between 1610 and 1617. It can be seen as part of Russia''s Time of Troubles, and is mainly remembered for the attempt to put a Swedish duke on the Russian throne.', 1610, NULL, NULL, 1617, NULL, NULL, 'year', '1610–1617', 64, 'https://en.wikipedia.org/wiki/Ingrian_War'),
  ('Q241108', 'Battle of Friedland', 'The Battle of Friedland (14 June 1807) was a major engagement of the Napoleonic Wars between the armies of the French Empire and the Russian Empire, led by Napoleon I and General Levin August von Bennigsen respectively. Napoleon and the French obtained a decisive victory that routed much of the Russian army, which retreated chaotically over the Alle river by the end of the fighting.', 1807, 6, 14, NULL, NULL, NULL, 'day', '14 June 1807', 71, 'https://en.wikipedia.org/wiki/Battle_of_Friedland'),
  ('Q184320', 'Battle of Borodino', 'The Battle of Borodino or the Battle of the Moskva took place on the outskirts of Moscow near the village of Borodino on 7 September 1812, during Napoleon''s invasion of Russia. The Grande Armée fought against the Imperial Russian Army.', 1812, 9, 7, NULL, NULL, NULL, 'day', '7 September 1812', 79, 'https://en.wikipedia.org/wiki/Battle_of_Borodino'),
  ('Q1071578', 'Battle of Smolensk', 'The Battle of Smolensk was the first major battle of the French invasion of Russia. It took place on 16–18 August 1812 and involved about 45,000 men of the Grande Armée under Emperor Napoleon I against about 30,000 Russian troops under General Barclay de Tolly.', 1812, NULL, NULL, 1812, 8, 18, 'year', '1812', 65, 'https://en.wikipedia.org/wiki/Battle_of_Smolensk_(1812)'),
  ('Q757870', 'Charge of the Light Brigade', 'The Charge of the Light Brigade was a military action undertaken by British light cavalry against Russian forces during the Battle of Balaclava in the Crimean War, resulting in many casualties to the cavalry. On 25 October 1854, the Light Brigade, led by Lord Cardigan, mounted a frontal assault against a Russian artillery battery which was well-prepared with excellent fields of defensive fire.', 1854, 10, 25, NULL, NULL, NULL, 'day', '25 October 1854', 64, 'https://en.wikipedia.org/wiki/Charge_of_the_Light_Brigade'),
  ('Q815216', 'Siege of Sevastopol', 'The Siege of Sevastopol (at the time called in English the Siege of Sebastopol) lasted from October 1854 until September 1855, during the Crimean War. The allies (French, Sardinian, Ottoman, and British) landed at Eupatoria on 14 September 1854, intending to make a triumphal march to Sevastopol, the capital of the Crimea, with 50,000 men.', 1854, NULL, NULL, 1855, 9, 9, 'year', '1854 – 9 September 1855', 65, 'https://en.wikipedia.org/wiki/Siege_of_Sevastopol_(1854%E2%80%931855)'),
  ('Q913604', 'Battle of Alma', 'The Battle of the Alma (short for Battle of the Alma River) took place during the Crimean War between an allied expeditionary force (made up of French, British, and Ottoman forces) and Russian forces defending the Crimean Peninsula on 20 September 1854. The allies had made a surprise landing in Crimea on 14 September.', 1854, 9, 20, NULL, NULL, NULL, 'day', '20 September 1854', 66, 'https://en.wikipedia.org/wiki/Battle_of_the_Alma'),
  ('Q149560', 'Battle of Stallupönen', 'The Battle of Stallupönen, fought between Russian and German armies on August 17, 1914, was the opening battle of World War I on the Eastern Front. The Germans under the command of Hermann von François conducted a successful counterattack against four Russian infantry divisions from different infantry corps, which heavily outnumbered them but were separated from each other, creating a gap between the 27th Infantry Division and the 40th Infantry Division, and had little coordination with each other.', 1914, 8, 17, NULL, NULL, NULL, 'day', '17 August 1914', 64, 'https://en.wikipedia.org/wiki/Battle_of_Stallup%C3%B6nen'),
  ('Q660655', 'First Battle of the Masurian Lakes', 'The First Battle of the Masurian Lakes was a German offensive in the Eastern Front 2–16 September 1914, during the Russian invasion of East Prussia. It took place only days after the Battle of Tannenberg where the German 8th Army encircled and destroyed the Russian 2nd Army.', 1914, 9, 7, 1914, 9, 14, 'day', '7 September 1914 – 14 September 1914', 68, 'https://en.wikipedia.org/wiki/First_Battle_of_the_Masurian_Lakes'),
  ('Q208300', 'Kronstadt rebellion', 'The Kronstadt rebellion (Russian: Кронштадтское восстание, romanized: Kronshtadtskoye vosstaniye) was a 1921 insurrection of Soviet sailors, naval infantry, and civilians against the Bolshevik government in the Russian port city of Kronstadt. Located on Kotlin Island in the Gulf of Finland, Kronstadt defended the former capital city, Petrograd (now Saint Petersburg), as the base of the Baltic Fleet.', 1921, NULL, NULL, 1921, 3, 18, 'year', '1921', 77, 'https://en.wikipedia.org/wiki/Kronstadt_rebellion'),
  ('Q697579', 'Battle of Lake Khasan', 'The Battle of Lake Khasan (Russian: Хасанские бои), also known as the Changkufeng Incident (Chinese and Japanese: 張鼓峰事件; Chinese pinyin: Zhānggǔfēng Shìjiàn; Japanese romaji: Chōkohō Jiken), was an attempted military incursion by Manchukuo, a Japanese puppet state, into territory claimed and controlled by the Soviet Union. The incursion, which occurred from 29 July to 11 August 1938, was founded in the Japanese belief that the Soviet Union had misinterpreted the demarcation of the boundary based on the Treaty of Peking between Imperial Russia and Qing China, and had subsequently tampered…', 1938, NULL, NULL, 1938, 8, 11, 'year', '1938', 68, 'https://en.wikipedia.org/wiki/Battle_of_Lake_Khasan'),
  ('Q154860', 'Siege of Sevastopol', 'The siege of Sevastopol, also known as the defence of Sevastopol (Russian: Оборона Севастополя, romanized: Oborona Sevastopolya) or the Battle for Sevastopol (German: Schlacht um Sewastopol; Romanian: Bătălia de la Sevastopol; Russian: Битва за Севастополь, romanized: Bitva za Sevastopol''), was a military engagement that took place on the Eastern Front of the Second World War. The campaign was fought by the Axis powers of Germany and Romania against the Soviet Union for control of Sevastopol, a port in Crimea on the Black Sea.', 1941, 10, 30, 1942, 7, 4, 'day', '30 October 1941 – 4 July 1942', 71, 'https://en.wikipedia.org/wiki/Siege_of_Sevastopol_(1941%E2%80%931942)'),
  ('Q169436', 'Battle of Rostov', 'The Battle of Rostov (1941) took place on the Eastern Front of World War II around Rostov-on-Don and was fought between Army Group South of Nazi Germany and the Southern Front of the Soviet Union. The battle comprised three phases: the German Sea of Azov Offensive Operation by Army Group South (General Gerd von Rundstedt) (begun on 12 September 1941), the Soviet Rostov Defensive Operation (5 November 1941 – 16 November 1941) by the Southern Front (General Yakov Timofeyevich Cherevichenko), and the Rostov Offensive Operation (27 November 1941 – 2 December 1941) executed by the same Soviet…', 1941, NULL, NULL, 1941, 12, 2, 'year', '1941', 67, 'https://en.wikipedia.org/wiki/Battle_of_Rostov_(1941)'),
  ('Q38789', 'Battle of Stalingrad', 'The Battle of Stalingrad was a major battle on the Eastern Front of World War II in which Nazi Germany and its Axis allies fought the Soviet Union for control of the city of Stalingrad (now Volgograd) in southern Russia. Marked by intense close-quarters combat and heavy civilian losses during aerial bombardment, the battle is considered the largest and deadliest urban battle in military history and the deadliest battle in World War II. By the end of the fighting, the German 6th Army had been destroyed, the 4th Panzer Army had suffered severe losses, and Army Group B was routed.', 1942, 8, 23, 1943, 2, 2, 'day', '23 August 1942 – 2 February 1943', 89, 'https://en.wikipedia.org/wiki/Battle_of_Stalingrad'),
  ('Q158287', 'Case Blue', 'Case Blue (German: Fall Blau) was the Wehrmacht''s plan for the 1942 summer offensive in southern Russia between 28 June and 24 November 1942, during World War II. The objective was to capture the oil fields of Baku (Azerbaijan SSR), Grozny and Maikop, to enable the Germans to obtain fuel and also to deny it to the Soviet Union, bringing about the complete collapse of the Soviet war effort. After Operation Barbarossa failed to destroy the Soviet Union as a political and military threat the previous year, Adolf Hitler recognized that Germany was now locked in a war of attrition and he was…', 1942, 11, 24, 1942, 11, 24, 'day', '24 November 1942', 68, 'https://en.wikipedia.org/wiki/Case_Blue'),
  ('Q161033', 'Demyansk Pocket', 'The Demyansk Pocket (German: Kessel von Demjansk; Russian: Демя́нский котёл) was the name given to the pocket of German troops encircled by the Red Army around Demyansk, south of Leningrad, on World War II''s Eastern Front. The pocket existed mainly from 8 February to 21 April 1942.', 1942, 5, 20, 1942, 5, 25, 'day', '20 May 1942 – 25 May 1942', 65, 'https://en.wikipedia.org/wiki/Demyansk_Pocket'),
  ('Q261776', 'Battles of Rzhev', 'The Battles of Rzhev (Russian: Ржевская битва, romanized: Rzhevskaya bitva) were a series of Red Army offensives against the Wehrmacht between 8 January 1942 and 31 March 1943, on the Eastern Front of World War II. The battles took place in the northeast of Smolensk Oblast and the south of Tver Oblast, in and around the salient surrounding Rzhev. Due to the high losses suffered by the Red Army, the campaign became known by veterans and historians as the "Rzhev Meat Grinder" (Russian: Ржевская мясорубка, romanized: Rzhevskaya myasorubka).', 1942, 1, 8, 1943, 3, 21, 'day', '8 January 1942 – 21 March 1943', 64, 'https://en.wikipedia.org/wiki/Battles_of_Rzhev'),
  ('Q233278', 'Operation Spark', 'Operation Iskra (Russian: операция Искра, lit. ''Operation Spark''), a Soviet military operation in January 1943 during World War II, aimed to break the Wehrmacht''s siege of Leningrad. Planning for the operation began shortly after the failure of the Sinyavino Offensive.', 1943, 1, 12, 1943, 1, 30, 'day', '12 January 1943 – 30 January 1943', 64, 'https://en.wikipedia.org/wiki/Operation_Iskra'),
  ('Q275019', 'Battle of Smolensk', 'The second Smolensk operation (code naming "Suvorov"; 7 August – 2 October 1943) was a Soviet strategic offensive operation conducted by the Red Army as part of the Summer-Autumn Campaign of 1943. Staged almost simultaneously with the Lower Dnieper Offensive (13 August – 22 September), the offensive lasted two months and was led by General Andrei Yeremenko, commanding the Kalinin Front, and Vasily Sokolovsky, commanding the Western Front.', 1943, NULL, NULL, 1943, 10, 2, 'year', '1943', 66, 'https://en.wikipedia.org/wiki/Smolensk_operation'),
  ('Q541506', 'Battle of Prokhorovka', 'The Battle of Prokhorovka was fought on 12 July 1943 near Prokhorovka, 87 kilometres (54 mi) southeast of Kursk, in the Soviet Union, during the Second World War. Taking place on the Eastern Front, the engagement was part of the wider Battle of Kursk and occurred when the 5th Guards Tank Army of the Soviet Red Army attacked the II SS-Panzer Corps of the German Waffen-SS in one of the largest tank battles in history.', 1943, 7, 12, NULL, NULL, NULL, 'day', '12 July 1943', 66, 'https://en.wikipedia.org/wiki/Battle_of_Prokhorovka'),
  ('Q653470', 'Battle of the Caucasus', 'The Battle of the Caucasus was a series of Axis and Soviet operations in the Caucasus as part of the Eastern Front of World War II. On 25 July 1942, German troops captured Rostov-on-Don, opening the Caucasus region of the southern Soviet Union to the Germans and threatening the oil fields beyond at Maykop, Grozny, and ultimately Baku. Two days prior, Adolf Hitler had issued a directive to launch an operation into the Caucasus named Operation Edelweiß.', 1943, 10, 9, 1943, 10, NULL, 'day', '9 October 1943 – October 1943', 64, 'https://en.wikipedia.org/wiki/Battle_of_the_Caucasus'),
  ('Q1321586', 'Moscow Armistice', 'The Moscow Armistice was signed between Finland on one side and the Soviet Union and United Kingdom on the other side on 19 September 1944, ending the Continuation War. The Armistice restored the Moscow Peace Treaty of 1940, with a number of modifications.', 1944, 9, 19, NULL, NULL, NULL, 'day', '19 September 1944', 64, 'https://en.wikipedia.org/wiki/Moscow_Armistice'),
  ('Q748379', '1960 U-2 incident spy aircraft', 'On 1 May 1960, a United States U-2 spy plane, having taken off from Peshawar in Pakistan, was shot down by the Soviet Air Defence Forces in Sverdlovsk, Russia. It was conducting photographic aerial reconnaissance inside Soviet territory while being flown by American Central Intelligence Agency pilot Francis Gary Powers, as it was hit by a surface-to-air missile.', 1960, 5, 1, NULL, NULL, NULL, 'day', '1 May 1960', 71, 'https://en.wikipedia.org/wiki/1960_U-2_incident'),
  ('Q159644', 'Treaty on the Final Settlement with Respect to Germany', 'The Treaty on the Final Settlement with Respect to Germany (German: Vertrag über die abschließende Regelung in Bezug auf Deutschland), more commonly referred to as the Two Plus Four Agreement (Zwei-plus-Vier-Vertrag), is an international agreement that allowed the reunification of Germany in October 1990. It was negotiated in 1990 between the ''two'', the Federal Republic of Germany and the German Democratic Republic, in addition to the Four Powers which had occupied Germany at the end of World War II in Europe: France, the Soviet Union, the United Kingdom, and the United States.', 1990, 9, 12, NULL, NULL, NULL, 'day', '12 September 1990', 71, 'https://en.wikipedia.org/wiki/Treaty_on_the_Final_Settlement_with_Respect_to_Germany'),
  ('Q76986', 'Belovezh Accords', 'The Agreement on the creation of the Commonwealth of Independent States (officially), or unofficially the Minsk Agreement and best known as the Belovezha Accords, is the agreement declaring that the Soviet Union (USSR) had effectively ceased to exist and establishing the Commonwealth of Independent States (CIS) in its place as an organization created by the same Union Republics. The documentation was signed at the state dacha near Viskuli in Belovezhskaya Pushcha, Belarus on 8 December 1991, by leaders of three of the four republics (except for the defunct Transcaucasian SFSR) which had…', 1991, 12, 8, NULL, NULL, NULL, 'day', '8 December 1991', 71, 'https://en.wikipedia.org/wiki/Belovezha_Accords'),
  ('Q931492', 'START I', 'START I (Strategic Arms Reduction Treaty) was a bilateral treaty between the United States and the Soviet Union on the reduction and the limitation of strategic offensive arms. The treaty was signed on 31 July 1991 and entered into force on 5 December 1994.', 1991, 7, 31, NULL, NULL, NULL, 'day', '31 July 1991', 67, 'https://en.wikipedia.org/wiki/START_I'),
  ('Q2679354', '1991 Soviet Union referendum', 'A referendum on the future of the Soviet Union was held on 17 March 1991 across the Soviet Union. It was the only national referendum in the history of the Soviet Union, although it was boycotted by authorities in six of the fifteen Soviet republics.', 1991, 3, 17, NULL, NULL, NULL, 'day', '17 March 1991', 65, 'https://en.wikipedia.org/wiki/1991_Soviet_Union_referendum'),
  ('Q862099', '1993 Russian constitutional crisis', 'In September and October 1993, following the increasingly visible tensions after December 1992, a constitutional crisis arose in the Russian Federation from a conflict between the then Russian president Boris Yeltsin and the country''s parliament. Yeltsin performed a self-coup, dissolving parliament and instituting a presidential rule by decree system.', 1993, NULL, NULL, 1993, 10, 4, 'year', '1993', 71, 'https://en.wikipedia.org/wiki/1993_Russian_constitutional_crisis'),
  ('Q29269', 'First Chechen War', 'The First Chechen War, also referred to as the First Russo-Chechen War, was a conflict between the separatist Chechen Republic of Ichkeria and the Russian Federation from 1994 to 1996. The conflict ended in a peace treaty that saw Russian forces withdraw from the territory only for them to invade again three years later, sparking the Second Chechen War of 1999–2009.', 1994, 12, 11, 1996, 8, 31, 'day', '11 December 1994 – 31 August 1996', 83, 'https://en.wikipedia.org/wiki/First_Chechen_War'),
  ('Q381461', 'Aeroflot Flight 593', 'Aeroflot Flight 593 was a scheduled international passenger flight from Sheremetyevo International Airport, Moscow, Russia, to Kai Tak Airport in Hong Kong. On 23 March 1994, the aircraft operating the route, an Airbus A310 flown by Aeroflot, crashed into the Kuznetsk Alatau mountain range in Kemerovo Oblast, killing all 63 passengers and 12 crew members on board.', 1994, 3, 23, NULL, NULL, NULL, 'day', '23 March 1994', 66, 'https://en.wikipedia.org/wiki/Aeroflot_Flight_593'),
  ('Q1142572', '1998 Russian financial crisis', 'The Russian financial crisis (also called the ruble crisis or the Russian flu) began in Russia on 17 August 1998. It resulted in the Russian government and the Russian Central Bank devaluing the ruble and defaulting on its debt.', 1998, NULL, NULL, 1998, 11, 15, 'year', '1998', 67, 'https://en.wikipedia.org/wiki/1998_Russian_financial_crisis'),
  ('Q4157877', 'Monetary reform in Russia, 1998', 'Russia launched a monetary reform on January 1, 1998. Preparation started in August 1997.', 1998, 1, 1, NULL, NULL, NULL, 'day', '1 January 1998', 30, 'https://en.wikipedia.org/wiki/1998_Russian_monetary_reform'),
  ('Q120843', 'Second Chechen War', 'The Second Chechen War (Russian: Втора́я чече́нская война́, Chechen: Шолгӏа оьрсийн-нохчийн тӏом, lit. ''Second Russian-Chechen War'') took place in Chechnya and the border regions of the North Caucasus between the Russian Federation and the breakaway Chechen Republic of Ichkeria, from August 1999 to April 2009. In August 1999, Islamists from Chechnya infiltrated Dagestan in Russia.', 1999, 8, 26, 2009, 4, 16, 'day', '26 August 1999 – 16 April 2009', 79, 'https://en.wikipedia.org/wiki/Second_Chechen_War'),
  ('Q193733', 'Beslan school siege', 'The Beslan school siege, also referred to as the Beslan terror attack, the Beslan tragedy, or the Beslan massacre, was an Islamist terrorist attack that occurred from 1 September 2004 to 3 September 2004 in Beslan, North Ossetia, Russia. It lasted three days, and involved the imprisonment of more than 1,100 people as hostages, including 777 children.', 2004, 9, NULL, 2004, 9, 3, 'month', 'September 2004 – 3 September 2004', 76, 'https://en.wikipedia.org/wiki/Beslan_school_siege'),
  ('Q131311', 'Smolensk air disaster', 'On 10 April 2010, a Tupolev Tu-154 aircraft operating as Polish Air Force Flight PLF 101, crashed near the Russian city of Smolensk, killing all 96 people on board. Among the victims were the president of Poland, Lech Kaczyński, and a number of senior Polish military officers, Polish government officials, and members of the Polish clergy, as well as relatives of victims of the Katyn massacre.', 2010, 4, 10, NULL, NULL, NULL, 'day', '10 April 2010', 79, 'https://en.wikipedia.org/wiki/Smolensk_air_disaster'),
  ('Q2002064', 'New START', 'New START was a nuclear arms reduction treaty between the United States and Russia with the formal name of Measures for the Further Reduction and Limitation of Strategic Offensive Arms. It was signed on 8 April 2010 in Prague, and after ratification it entered into force on 5 February 2011.', 2010, 4, 8, 2021, 2, 5, 'day', '8 April 2010 – 5 February 2021', 64, 'https://en.wikipedia.org/wiki/New_START'),
  ('Q182085', '2011 Lokomotiv Yaroslavl air disaster', 'On 7 September 2011, YAK-Service Flight 9633, a Yakovlev Yak-42 carrying players and coaching staff of the Lokomotiv Yaroslavl professional ice hockey team, crashed during take-off near Yaroslavl, Yaroslavl Oblast, Russia. All but one of the 45 people on board were killed.', 2011, 9, 7, NULL, NULL, NULL, 'day', '7 September 2011', 73, 'https://en.wikipedia.org/wiki/Lokomotiv_Yaroslavl_plane_crash'),
  ('Q629636', '2011–2013 Russian protests', 'The 2011–2013 Russian protests, which some English language media referred to as the Snow Revolution (Russian: Снежная революция, romanised: Snezhnaya revolyutsiya), began in 2011 (as protests against the 2011 Russian legislative election results) and continued into 2012 and 2013. The protests were motivated by claims of Russian and foreign journalists, political activists and members of the public that the election process was fraudulent.', 2011, 12, 4, 2013, 7, 18, 'day', '4 December 2011 – 18 July 2013', 65, 'https://en.wikipedia.org/wiki/2011%E2%80%932013_Russian_protests'),
  ('Q15198571', 'Tatarstan Airlines Flight 363', 'Tatarstan Airlines Flight 363 was a scheduled domestic passenger flight, operated by Tatarstan Airlines on behalf of Ak Bars Aero, from Moscow to Kazan, Russia. On 17 November 2013, at 19:24 local time (UTC+4), the Boeing 737-500 crashed during an aborted landing at Kazan International Airport, killing all 44 passengers and 6 crew members on board.', 2013, 11, 17, NULL, NULL, NULL, 'day', '17 November 2013', 66, 'https://en.wikipedia.org/wiki/Tatarstan_Airlines_Flight_363'),
  ('Q15920546', 'Russian annexation of Crimea', 'In February and March 2014, Russia invaded the Crimean Peninsula of Ukraine, occupied it, and then annexed it after an illegitimate referendum. This took place amid the uncertainty that immediately followed Ukraine''s Revolution of Dignity.', 2014, NULL, NULL, 2014, 3, 26, 'year', '2014', 81, 'https://en.wikipedia.org/wiki/2014_Russian_annexation_of_Crimea'),
  ('Q112222097', 'child abductions in the Russo-Ukrainian war', 'During the Russo-Ukrainian war, Russia has forcibly transferred almost 20,000 Ukrainian children to areas under its control, assigned them Russian citizenship, forcibly adopted them into Russian families, and created obstacles for their reunification with their parents and homeland. The International Criminal Court (ICC) has issued arrest warrants for President of Russia Vladimir Putin (who has explicitly supported the forced adoptions, including by enacting legislation to facilitate them) and Children''s Rights Commissioner Maria Lvova-Belova for their alleged involvement.', 2014, NULL, NULL, NULL, NULL, NULL, 'year', '2014', 67, 'https://en.wikipedia.org/wiki/Child_abductions_in_the_Russo-Ukrainian_war'),
  ('Q23253749', 'Flydubai Flight 981', 'Flydubai Flight 981 (FZ981/FDB981) was a scheduled international passenger flight from Dubai, United Arab Emirates, to Rostov-on-Don, Russia. On 19 March 2016, the Boeing 737-800 aircraft operating the flight crashed during a go-around, killing all 62 passengers and crew on board.', 2016, 3, 19, NULL, NULL, NULL, 'day', '19 March 2016', 68, 'https://en.wikipedia.org/wiki/Flydubai_Flight_981'),
  ('Q28055770', '2016 Russian Defence Ministry Tupolev Tu-154 crash', 'On 25 December 2016, a Tupolev Tu-154 jetliner of the Russian Defence Ministry crashed into the Black Sea shortly after taking off from Sochi International Airport, Russia, while en route to Khmeimim Air Base, Syria, during the Russian military intervention in the war in Syria. All 92 passengers and crew on board, including 64 members of the Alexandrov Ensemble choir of the Russian Armed Forces, were killed.', 2016, 12, 25, NULL, NULL, NULL, 'day', '25 December 2016', 70, 'https://en.wikipedia.org/wiki/2016_Russian_Defence_Ministry_Tupolev_Tu-154_crash'),
  ('Q29113584', '2017 Saint Petersburg Metro attack', 'On 3 April 2017, a terrorist attack using an explosive device took place on the Saint Petersburg Metro between Sennaya Ploshchad and Tekhnologichesky Institut stations. Eleven people (including the perpetrator) were initially reported to have died, and five more died later from their injuries, bringing the total to 15.', 2017, 4, 3, NULL, NULL, NULL, 'day', '3 April 2017', 74, 'https://en.wikipedia.org/wiki/2017_Saint_Petersburg_Metro_bombing'),
  ('Q59199697', 'Kerch Strait incident', 'The Kerch Strait incident was an international incident that occurred on 25 November 2018 in the Kerch Strait, during which the Russian Federal Security Service (FSB) coast guard fired upon and captured three Ukrainian Navy vessels after they attempted to transit from the Black Sea into the Sea of Azov through the strait on their way to the port of Mariupol. It was the first time that Russian forces had openly engaged Ukrainian forces during the Russo-Ukrainian War.', 2018, 11, 25, NULL, NULL, NULL, 'day', '25 November 2018', 67, 'https://en.wikipedia.org/wiki/Kerch_Strait_incident'),
  ('Q63490143', 'Aeroflot Flight 1492', 'Aeroflot Flight 1492 was a scheduled domestic passenger flight operated by Aeroflot from Moscow–Sheremetyevo to Murmansk, Russia. On 5 May 2019, the Sukhoi Superjet 100 aircraft operating the flight was climbing out when it was struck by lightning.', 2019, 5, 5, NULL, NULL, NULL, 'day', '5 May 2019', 68, 'https://en.wikipedia.org/wiki/Aeroflot_Flight_1492'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q101429497', '2020 Nagorno-Karabakh ceasefire agreement', 'The 2020 Nagorno-Karabakh ceasefire agreement was an armistice agreement that ended the Second Nagorno-Karabakh War. It was signed on 9 November by the President of Azerbaijan Ilham Aliyev, the Prime Minister of Armenia Nikol Pashinyan and the President of Russia Vladimir Putin, and ended all hostilities in the Nagorno-Karabakh region from 00:00, on 10 November 2020 Moscow time.', 2020, 11, 9, NULL, NULL, NULL, 'day', '9 November 2020', 69, 'https://en.wikipedia.org/wiki/2020_Nagorno-Karabakh_ceasefire_agreement'),
  ('Q105008734', '2021 Russian protests', 'The 2021 Russian protests, also known as Navalny Protests, began on 23 January 2021 in support of the opposition leader Alexei Navalny after he was immediately detained upon returning to Russia after being sent to Germany for treatment following his poisoning the previous year. Days before protests began, a film by Navalny and his Anti-Corruption Foundation (FBK) called Putin''s Palace, which revolves around the connection between president Vladimir Putin and a palace allegedly being built for him, was released.', 2021, NULL, NULL, NULL, NULL, NULL, 'year', '2021', 68, 'https://en.wikipedia.org/wiki/2021_Russian_protests'),
  ('Q110999040', 'full-scale Russo-Ukrainian war', 'On 24 February 2022, Russia invaded Ukraine, starting the largest and deadliest war in Europe since World War II, in a major escalation of the existing war between the two countries that began when Russia attacked Ukraine in 2014. The fighting has caused hundreds of thousands of military casualties and tens of thousands of Ukrainian civilian casualties.', 2022, 2, 24, NULL, NULL, NULL, 'day', '24 February 2022', 98, 'https://en.wikipedia.org/wiki/Russo-Ukrainian_war_(2022%E2%80%93present)'),
  ('Q114492886', '2022 Crimean Bridge explosion', 'The 2022 Crimean Bridge explosion occurred on 8 October 2022, at 6:07 a.m. A fire broke out on the Crimean Bridge as a result of an explosion of a bomb that had been loaded onto a truck.', 2022, 10, 8, NULL, NULL, NULL, 'day', '8 October 2022', 68, 'https://en.wikipedia.org/wiki/2022_Crimean_Bridge_explosion'),
  ('Q119860532', 'Wagner Group rebellion', 'On 23 June 2023, the Wagner Group, a Russian private military company, staged an uprising against the Russian government. It marked the climax of the Wagner Group–Ministry of Defense conflict, which had begun about six months earlier.', 2023, 6, NULL, 2023, 6, 24, 'month', 'June 2023 – 24 June 2023', 80, 'https://en.wikipedia.org/wiki/Wagner_Group_rebellion'),
  ('Q125092492', 'Crocus City Hall attack', 'On 22 March 2024, a coordinated terrorist attack against civilians occurred at the Crocus City Hall music venue in Crocus City, Krasnogorsk, Moscow Oblast, Russia. The attack began at around 20:00 MSK (UTC+3), shortly before the Russian band Picnic was scheduled to play a sold-out show at the venue.', 2024, 3, 22, 2024, 3, 22, 'day', '22 March 2024', 81, 'https://en.wikipedia.org/wiki/Crocus_City_Hall_attack');
